{
  "justification": "I mapped the unprompted salience of issues to the foundations and weighted each foundation by the combined prominence of its associated topics, acknowledging that the survey records importance, not direction. High salience for NHS/health, immigration, and the economy boosts Care, Loyalty, and Proportionality respectively; crime/governance and drugs/morality/environment sustain Authority and Sanctity, while inequality, low pay, and access to services support a substantial Equality component.",
  "foundations": [
    {
      "foundation": "care",
      "basis": "NHS/Hospitals/Healthcare; Education/Schools; Housing; Poverty/Inequality; Pensions/Social security; Ageing population/Social care; Public services in general; Animal welfare",
      "weight": 0.27
    },
    {
      "foundation": "loyalty",
      "basis": "Immigration; Defence/Foreign affairs/International terrorism; Common Market/EU/Europe/Single European Currency; Scottish/Welsh Assembly/Devolution; Nuclear weapons/Disarmament; Trade unions/Strikes; Countryside/Rural life",
      "weight": 0.19
    },
    {
      "foundation": "authority",
      "basis": "Crime/Law and order/Violence/Vandalism; Local government/Council tax/Poll tax; Lack of faith in govt/politics; Nationalisation/Government control; Defence/Foreign affairs/International terrorism; Drug abuse; Morality/Individual behaviour/Lifestyle; Transport/Public transport",
      "weight": 0.15
    },
    {
      "foundation": "sanctity",
      "basis": "Drug abuse; Morality/Individual behaviour/Lifestyle; Pollution/Environment; Countryside/Rural life",
      "weight": 0.09
    },
    {
      "foundation": "equality",
      "basis": "Poverty/Inequality; Low pay/Minimum wage/Fair wages; Race relations; Education/Schools; Housing; Public services in general; NHS/Hospitals/Healthcare",
      "weight": 0.14
    },
    {
      "foundation": "proportionality",
      "basis": "Economy/Economic situation; Unemployment/Factory closure/Lack of industry; Taxation; Inflation/Prices; Local government/Council tax/Poll tax; Privatisation; Petrol prices/Fuel; Pound/Exchange rate; Low pay/Minimum wage/Fair wages",
      "weight": 0.16
    }
  ]
}
